// League Dashboard — top-level page.
//
// Wired to the REAL leagues API through useLeagueDashboard (token + viewer
// identity resolved, endpoints fetched in parallel, mapped to the dashboard's
// domain shapes). Components read the mapped data via their existing prop
// contracts. Switching leagues is a route change (/leagues/:id/dashboard) so the
// whole page repopulates from the new dataset.

import { useEffect, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";

import MainLayout from "../../components/MainLayout";
import { useAuth } from "../../context/AuthContext";
import { buildLeagueChallengeState } from "../../pages/leagueLadder";
import ActionSlot from "./ActionSlot";
import Hero from "./Hero";
import Icon from "./Icon";
import LeagueSwitcher from "./LeagueSwitcher";
import LeagueSectionsV2, { SCHEDULE_SECTIONS, type ScheduleSectionKey } from "./LeagueSectionsV2";
import LeagueTabs from "./LeagueTabs";
import LessonsAtYourLevel from "./LessonsAtYourLevel";
import PlayersLooking from "./PlayersLooking";
import ResultsTicker from "./ResultsTicker";
import SeasonProgress from "./SeasonProgress";
import SectionNav, { type SectionKey } from "./SectionNav";
import StandingsPreview from "./StandingsPreview";
import ThisWeekCard from "./ThisWeekCard";
import { challengeService } from "./challengeService";
import { useIsMobile } from "./useIsMobile";
import { cancelHostedMatch, leaveMatch } from "../../api/matches";
import { getStoredAuthToken } from "../../services/authToken";
import { useBestBets } from "./useBestBets";
import { useLeagueDashboard } from "./useLeagueDashboard";
import { useLevelMatchedLessons } from "./useLevelMatchedLessons";
import { isHomeV2Enabled, isLeagueCoachingPromptsEnabled } from "../../utils/featureFlags";
import { track } from "../../utils/analytics";
import type { NextMoveTarget, TabKey } from "./types";

// The cancel dialog reuses the .league-confirm panel defined in LeaguesPage.css. That
// file is already in the single global stylesheet today, so this import changes no
// output — it declares the dependency so the dialog does not silently lose its styling
// if CSS code-splitting is ever turned on.
import "../../pages/LeaguesPage.css";
import "./LeagueDashboard.css";

const LeagueDashboardPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  // Cancelling notifies the other player, so it confirms first rather than firing off
  // a row button. Host cancels the match; a player who accepted withdraws from it.
  const [cancelTarget, setCancelTarget] = useState<{ id: string | number; viewerIsHost: boolean } | null>(null);
  const [cancelBusy, setCancelBusy] = useState(false);
  const [cancelError, setCancelError] = useState<string | null>(null);

  const confirmCancelScheduled = async () => {
    if (!cancelTarget) return;
    setCancelBusy(true);
    setCancelError(null);
    try {
      const token = getStoredAuthToken({ preferScheme: "token" });
      if (cancelTarget.viewerIsHost) {
        await cancelHostedMatch({ matchId: cancelTarget.id, token });
      } else {
        await leaveMatch({ matchId: cancelTarget.id, token });
      }
      setCancelTarget(null);
      reload();
    } catch (err) {
      setCancelError(err instanceof Error ? err.message : "Couldn't cancel this match.");
    } finally {
      setCancelBusy(false);
    }
  };
  const { data, hero, nextMove, leagues, loading, error, reload } = useLeagueDashboard(id);

  // Coaching prompts: the lessons card, the ladder nudge and the hero's clinic link.
  const coachingEnabled = isLeagueCoachingPromptsEnabled();
  const matchedLessons = useLevelMatchedLessons({ enabled: coachingEnabled, leagueLabel: data?.summary.level });
  const coachingLeagueId = String(data?.summary.id ?? id ?? "");
  const coachingReady = coachingEnabled && matchedLessons.loaded && Boolean(matchedLessons.level && matchedLessons.band);
  const ladderNudge = coachingReady
    ? {
        leagueId: coachingLeagueId,
        band: matchedLessons.band as string,
        next: matchedLessons.lessons[0] ?? null,
        linkState: matchedLessons.linkState,
      }
    : null;
  const heroClinic = coachingReady
    ? {
        level: matchedLessons.level as string,
        linkState: matchedLessons.linkState,
        onClick: () => track("hero_clinic_click", { leagueId: coachingLeagueId, levelBand: matchedLessons.band }),
      }
    : null;
  const lessonsCard = coachingEnabled ? <LessonsAtYourLevel leagueId={coachingLeagueId} matched={matchedLessons} /> : null;
  const [activeTab, setActiveTab] = useState<TabKey>("ladder");
  // Mobile section state (Overview + the four data tabs). Kept separate from the
  // desktop `activeTab` so "overview" can never leak into the desktop LeagueTabs.
  const [section, setSection] = useState<SectionKey>("overview");
  // Home v2: the page is Schedule · Standings · Results (LeagueSectionsV2), on both branches.
  const scheduleOn = isHomeV2Enabled();
  const [schedSection, setSchedSection] = useState<ScheduleSectionKey>("schedule");
  const bestBets = useBestBets(data?.summary.id, scheduleOn && Boolean(data) && !data?.summary.archived);

  // "See full standings" (mobile Overview preview) switches to the Standings
  // section AND moves focus into the panel for keyboard/AT users. The panel only
  // mounts once `section !== "overview"`, so we flip a pending-focus flag and let
  // an effect focus the wrapper after it commits (robust vs. same-tick refs).
  const panelRef = useRef<HTMLDivElement>(null);
  const [pendingPanelFocus, setPendingPanelFocus] = useState(false);
  const goStandings = () => {
    setSection("standings");
    setPendingPanelFocus(true);
  };
  useEffect(() => {
    if (pendingPanelFocus && section === "standings") {
      panelRef.current?.focus();
      setPendingPanelFocus(false);
    }
  }, [pendingPanelFocus, section]);

  // Reset to the default tab/section whenever the active league changes.
  useEffect(() => {
    setActiveTab("ladder");
    setSection("overview");
    setSchedSection("schedule");
  }, [data?.summary.id]);

  // Jump to the Pending list from either branch's affordances (banner "View",
  // respond-to-challenge next move). Sets both states so it works whichever
  // branch is mounted.
  const showPending = () => {
    setActiveTab("pending");
    setSection("pending");
    setSchedSection("schedule");
  };

  // Hand off to the existing LeagueDetailPage flows via router state (the same
  // channel MatchBrowserPage uses): openPost → Need-a-Match drawer,
  // acceptSuggestionId → the confirm-and-join accept flow.
  const goLeague = (state?: Record<string, unknown>) =>
    navigate(`/leagues/${id}`, state ? { state } : undefined);

  // "Need a Match" / "Post availability" goes to the multi-slot Post Availability
  // page (merged from main via #250).
  const goPostAvailability = () =>
    navigate(`/leagues/${id}/post-availability`, { state: { returnTo: `/leagues/${id}/dashboard` } });

  // "Log a Score" opens the shared /log-result flow with this league preselected,
  // so recording a result from the dashboard mirrors the global Log a Score entry.
  const goLogScore = () =>
    navigate("/log-result", { state: { matchType: "league", leagueId: id } });

  // Viewer's own first name for the outreach message. Read-only use of auth state.
  const { user } = useAuth() as { user?: Record<string, unknown> };
  const viewerName = String(
    (user?.full_name as string | undefined)
      ?? ((user?.profile as Record<string, unknown> | undefined)?.full_name as string | undefined)
      ?? (user?.name as string | undefined)
      ?? "",
  );

  // Contact sheet → the same match-create flow the ladder's Challenge button uses.
  // Prefer the ladder row (it carries court and rating context); fall back to the
  // roster entry for players who are not yet rated onto the ladder.
  const goProposeMatch = (playerId: string) => {
    const ladderRow = data?.ladder.find((item) => item.playerId === playerId);
    if (ladderRow) {
      if (ladderRow.isViewer) return;
      navigate("/matches/create", {
        state: buildLeagueChallengeState({ row: ladderRow, leagueName: data?.summary.name }),
      });
      return;
    }
    const player = data?.roster.find((item) => item.playerId === playerId);
    if (!player) return;
    navigate("/matches/create", {
      state: {
        connectIntent: {
          invitee: {
            id: player.playerId,
            name: player.name,
            // Unrated players carry no level rather than a fabricated one.
            level: player.rating === null ? "" : `TPR ${player.rating.toFixed(1)}`,
          },
          senderLevel: "",
          suggestedAvailability: [],
          preferredCourt: null,
          source: "league-players",
          senderName: data?.summary.name || "League",
        },
      },
    });
  };

  const goChallenge = (playerId: string) => {
    const row = data?.ladder.find((item) => item.playerId === playerId);
    if (!row || row.isViewer) return;
    navigate("/matches/create", {
      state: buildLeagueChallengeState({
        row,
        leagueName: data?.summary.name,
      }),
    });
  };

  const handleNextMove = (target: NextMoveTarget) => {
    switch (target) {
      case "add-score":
        goLogScore();
        break;
      case "add-availability":
        goPostAvailability();
        break;
      case "schedule-candidate": {
        const sid = data?.nextMoveContext.matchmake_candidate?.suggestionId;
        if (sid != null) goLeague({ acceptSuggestionId: sid });
        else goPostAvailability();
        break;
      }
      case "all-matches":
        navigate(`/leagues/${id}/match-browser`);
        break;
      case "direct-challenge": {
        // FLAG: no real direct-challenge backend yet — stubbed via challengeService.
        const opponent = data?.nextMoveContext.unplayed_opponents[0];
        if (opponent) void challengeService.challenge(String(opponent.playerId));
        break;
      }
      case "respond-challenge":
        // No challenges endpoint yet (Rung 0 "respond" is dormant) — show pending.
        showPending();
        break;
      case "notify-me":
      default:
        break;
    }
  };

  // Home v2's sections (LeagueSectionsV2) reuse the same prompt, list and handlers as below.
  const actionSlotFor = (onRespond: () => void) =>
    data ? (
      <ActionSlot
        reportOpponent={data.nextMoveContext.unscored_results[0]?.opponentName}
        challengeFrom={data.nextMoveContext.pending_challenges_for_me[0]?.fromName}
        lookingName={data.looking[0]?.name}
        playersLookingCount={data.playersLookingCount}
        onReport={() => goLogScore()}
        onRespond={onRespond}
        onSeeLooking={() => navigate(`/leagues/${id}/match-browser`)}
        onViewAll={() => navigate(`/leagues/${id}/match-browser`)}
      />
    ) : null;
  const lookingAndLessons = data ? (
    <>
      <PlayersLooking
        looking={data.looking}
        onNeedMatch={() => goPostAvailability()}
        onSeeAll={() => navigate(`/leagues/${id}/match-browser`)}
      />
      {lessonsCard}
    </>
  ) : null;
  // Home v2: Arrange opens the propose-times screen for an opponent with an unplayed fixture;
  // anyone else (a flex league with no fixture between you) still gets the create flow.
  const arrange = (playerId: string) => {
    if (data?.arrangeableOpponentIds?.includes(String(playerId))) {
      navigate(`/leagues/${id}/arrange/${playerId}`);
      return;
    }
    goProposeMatch(playerId);
  };
  const panelProps = {
    onSchedule: () => goPostAvailability(),
    onChallenge: goChallenge,
    onProposeMatch: scheduleOn ? arrange : goProposeMatch,
    viewerName,
    ladderNudge,
    onCancelScheduled: (matchId: string | number, viewerIsHost: boolean) => {
      setCancelError(null);
      setCancelTarget({ id: matchId, viewerIsHost });
    },
  };

  return (
    <MainLayout
      pageClassName="leagues-shell lgd-shell"
      hideMobileNewMatch
      hideMobileNotifications
      hideMobileLocation
      onMobileBack={() => navigate("/leagues")}
      mobileCenter={
        data ? <LeagueSwitcher variant="nav" active={data.summary} leagues={leagues} /> : undefined
      }
    >
      <div className={`lgd${isMobile ? " has-nextmove-bar lgd--mobile" : ""}`}>
        {(() => {
          const notReady = loading || !data || !hero || !nextMove;
          const loadingOrError = error ? (
            <section className="card" style={{ padding: 24 }}>
              <div className="t" style={{ fontWeight: 600, marginBottom: 6 }}>
                Couldn't load this league
              </div>
              <div className="b" style={{ color: "var(--ink-3)" }}>{error}</div>
            </section>
          ) : (
            <section className="card" style={{ padding: 24 }} aria-busy="true">
              Loading league…
            </section>
          );

          // ── Mobile branch: persistent segmented section-nav + section content.
          // No page-head / back link (nav carries the switcher + back arrow), so
          // the sticky section-nav sits flush under the top nav — no empty gap.
          if (isMobile) {
            if (notReady || !data || !hero || !nextMove) {
              return <div className="wrap">{loadingOrError}</div>;
            }
            if (scheduleOn) {
              return (
                <>
                  <SectionNav section={schedSection} onChange={setSchedSection} sections={SCHEDULE_SECTIONS} />
                  <div className="wrap">
                    <LeagueSectionsV2
                      data={data}
                      section={schedSection}
                      onSection={setSchedSection}
                      actionSlot={actionSlotFor(showPending)}
                      looking={lookingAndLessons}
                      bestBets={bestBets}
                      panel={panelProps}
                    />
                    <div className="mobile-foot">{data.summary.sub}</div>
                  </div>
                </>
              );
            }
            return (
              <>
                <SectionNav section={section} onChange={setSection} />
                <div className="wrap">
                  {section === "overview" ? (
                    <>
                      {/* Unified contextual slot (replaces the league-wide pending
                          banner + the next-move card on mobile). Shows ONE specific
                          named prompt the sticky bar can't express, or nothing. */}
                      <ActionSlot
                        reportOpponent={data.nextMoveContext.unscored_results[0]?.opponentName}
                        challengeFrom={data.nextMoveContext.pending_challenges_for_me[0]?.fromName}
                        lookingName={data.looking[0]?.name}
                        playersLookingCount={data.playersLookingCount}
                        onReport={() => goLogScore()}
                        onRespond={showPending}
                        onSeeLooking={() => navigate(`/leagues/${id}/match-browser`)}
                        onViewAll={() => navigate(`/leagues/${id}/match-browser`)}
                      />
                      <Hero
                        hero={hero}
                        onCta={() => handleNextMove(nextMove.cta.target)}
                        onPostAvailability={() => goPostAvailability()}
                        clinic={heroClinic}
                      />
                      <StandingsPreview standings={data.standings} onSeeFull={goStandings} />
                      <ResultsTicker items={data.ticker} />
                      <ThisWeekCard week={data.week} />
                      {lessonsCard}
                      <SeasonProgress season={data.season} />
                      <PlayersLooking
                        looking={data.looking}
                        onNeedMatch={() => goPostAvailability()}
                        onSeeAll={() => navigate(`/leagues/${id}/match-browser`)}
                      />
                    </>
                  ) : (
                    // Focus target for "See full standings" — tabIndex=-1 so it's
                    // programmatically focusable but not a keyboard tab stop.
                    <div ref={panelRef} tabIndex={-1} className="section-panel-wrap">
                      <LeagueTabs
                        data={data}
                        // Not "overview" in this branch — the four data tabs are TabKeys.
                        activeTab={section as TabKey}
                        onTabChange={setSection}
                        onSchedule={() => goPostAvailability()}
                        onChallenge={goChallenge}
                        onProposeMatch={goProposeMatch}
                        viewerName={viewerName}
                        onNeedMatch={() => goPostAvailability()}
                        hideTabBar
                        ladderNudge={ladderNudge}
                        onCancelScheduled={(matchId, viewerIsHost) => {
                          setCancelError(null);
                          setCancelTarget({ id: matchId, viewerIsHost });
                        }}
                      />
                    </div>
                  )}
                  <div className="mobile-foot">{data.summary.sub}</div>
                </div>
              </>
            );
          }

          // ── Desktop branch: the current layout, verbatim (pixel-identical).
          return (
            <div className="wrap">
              <a className="back" href="#/leagues">
                <Icon name="chevron-left" />
                Back to leagues
              </a>

              {notReady || !data || !hero || !nextMove ? (
                loadingOrError
              ) : (
                <>
                  <div className="page-head">
                    <LeagueSwitcher variant="page" active={data.summary} leagues={leagues} />
                    <div className="head-actions">
                      <button type="button" className="btn ghost" onClick={() => goPostAvailability()}>
                        Need a match
                      </button>
                      <button type="button" className="btn" onClick={() => goLogScore()}>
                        <Icon name="plus" />
                        Add score
                      </button>
                    </div>
                  </div>

                  {scheduleOn ? (
                    <LeagueSectionsV2
                      data={data}
                      section={schedSection}
                      onSection={setSchedSection}
                      showTabs
                      actionSlot={actionSlotFor(showPending)}
                      looking={lookingAndLessons}
                      bestBets={bestBets}
                      panel={panelProps}
                    />
                  ) : (
                  <>
                  {/* Unified contextual slot (replaces the league-wide pending
                      banner + the next-move card on desktop, mirroring mobile).
                      Full-width, top of content: ONE specific named prompt, or
                      nothing. Generic Need-a-match / Add-score live in head-actions. */}
                  <ActionSlot
                    reportOpponent={data.nextMoveContext.unscored_results[0]?.opponentName}
                    challengeFrom={data.nextMoveContext.pending_challenges_for_me[0]?.fromName}
                    lookingName={data.looking[0]?.name}
                    playersLookingCount={data.playersLookingCount}
                    onReport={() => goLogScore()}
                    onRespond={() => setActiveTab("pending")}
                    onSeeLooking={() => navigate(`/leagues/${id}/match-browser`)}
                    onViewAll={() => navigate(`/leagues/${id}/match-browser`)}
                  />

                  <Hero hero={hero} onCta={() => handleNextMove(nextMove.cta.target)} clinic={heroClinic} />

                  <ResultsTicker items={data.ticker} />

                  {/* Desktop card area: two columns, each pairing a tall list card
                      with a compact one so the tops align and the width is used.
                      Collapses to one column ≤860px (see .lgd-cols in CSS). */}
                  <section className="lgd-cols">
                    <div className="lgd-col">
                      <StandingsPreview standings={data.standings} onSeeFull={() => setActiveTab("standings")} />
                      <SeasonProgress season={data.season} />
                    </div>
                    <div className="lgd-col">
                      <PlayersLooking
                        looking={data.looking}
                        onNeedMatch={() => goPostAvailability()}
                        onSeeAll={() => navigate(`/leagues/${id}/match-browser`)}
                      />
                      <ThisWeekCard week={data.week} />
                      {lessonsCard}
                    </div>
                  </section>

                  <LeagueTabs
                    data={data}
                    activeTab={activeTab}
                    onTabChange={setActiveTab}
                    onSchedule={() => goPostAvailability()}
                    onChallenge={goChallenge}
                    onProposeMatch={goProposeMatch}
                    viewerName={viewerName}
                    // Desktop has no sticky bar. Deliberately no "Log a Score"
                    // here — nothing on a roster screen implies a finished match.
                    onNeedMatch={() => goPostAvailability()}
                    ladderNudge={ladderNudge}
                    onCancelScheduled={(matchId, viewerIsHost) => {
                      setCancelError(null);
                      setCancelTarget({ id: matchId, viewerIsHost });
                    }}
                  />
                  </>
                  )}
                </>
              )}
            </div>
          );
        })()}

        {cancelTarget ? (
          <div className="league-confirm" role="dialog" aria-modal="true" aria-label="Cancel this match">
            <div className="league-confirm__backdrop" onClick={() => setCancelTarget(null)} />
            <div className="league-confirm__panel">
              <h2>Cancel this match?</h2>
              <p className="league-confirm__note">
                Your opponent will be told. If the match is soon, message them as well so
                they have a chance to find another.
              </p>
              {cancelError ? <p className="league-need-error">{cancelError}</p> : null}
              <div className="league-confirm__actions">
                <button type="button" onClick={() => setCancelTarget(null)}>
                  Keep match
                </button>
                <button
                  type="button"
                  className="league-confirm__destructive"
                  disabled={cancelBusy}
                  onClick={() => void confirmCancelScheduled()}
                >
                  {cancelBusy ? "Cancelling..." : "Cancel match"}
                </button>
              </div>
            </div>
          </div>
        ) : null}

        {isMobile && data ? (
          <div className="nextmove-bar">
            <button type="button" className="btn" onClick={() => goLogScore()}>
              Log a score
            </button>
            <button type="button" className="btn ghost" onClick={() => goPostAvailability()}>
              Need a Match
            </button>
          </div>
        ) : null}
      </div>
    </MainLayout>
  );
};

export default LeagueDashboardPage;
